def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t)
            d = abs(tx - sx) + abs(ty - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = (tx, ty)
        return best

