                target = (tx, ty)
        if target is None:
            target = (cx, cy)
        return [sgn(target[0] - sx), sgn(target[1] - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("enemy_territory") or []
        target = nearest(targets, sx, sy)
        if target is None:
            target = nearest(observation.get("resources") or [], sx, sy)
