        return [sgn(target[0] - sx), sgn(target[1] - sy)]

    opp_targets = observation.get("opponent_territory") or observation.get("unclaimed_cells") or []
    target = nearest(opp_targets, sx, sy)
    if target is not None:
        return [sgn(target[0] - sx), sgn(target[1] - sy)]

    return [sgn(cx - sx), sgn(cy - sy)]

